# preprocess.py\n\n"""\nData preprocessing script.\nLoads raw text files, tokenizes using HuggingFace tokenizer, and saves a PyTorch dataset.\nUsage:\n    python preprocess.py --input_dir raw_data --output_dir data/processed\n"""\n\nimport os, argparse\nfrom pathlib import Path\nfrom transformers import AutoTokenizer\nimport torch\n\ndef load_texts(input_dir: Path):\n    texts = []\n    for file in input_dir.rglob('*.txt'):\n        with open(file, encoding='utf-8') as f:\n            texts.append(f.read())\n    return texts\n\ndef save_dataset(tokenized, output_path: Path):\n    torch.save(tokenized, output_path)\n\ndef main():\n    parser = argparse.ArgumentParser(description='Preprocess raw text data')\n    parser.add_argument('--input_dir', type=str, required=True, help='Directory with raw .txt files')\n    parser.add_argument('--output_dir', type=str, required=True, help='Where to store processed dataset')\n    parser.add_argument('--model_name', type=str, default='distilbert-base-uncased', help='Tokenizer model')\n    args = parser.parse_args()\n\n    input_path = Path(args.input_dir)\n    output_path = Path(args.output_dir) / 'dataset.pt'\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n\n    tokenizer = AutoTokenizer.from_pretrained(args.model_name, use_fast=True)\n    texts = load_texts(input_path)\n    tokenized = tokenizer(texts, padding='longest', truncation=True, return_tensors='pt')\n    save_dataset(tokenized, output_path)\n    print(f'Saved tokenized dataset to {output_path}')\n\nif __name__ == '__main__':\n    main()\n
